package com.prayeroverhead;

import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Prayer;
import net.runelite.api.gameval.SpriteID;

/**
 * Maps each standard-book prayer to its icon sprite. EnumMap iterates in enum
 * order, which matches prayer book order, so icons draw in a consistent order.
 * Prayers with no entry here (e.g. Ruinous Powers, or any prayer added after
 * this was written) are simply skipped.
 */
final class PrayerIcons
{
	static final Map<Prayer, Integer> SPRITES;

	/** Prayers the game already draws over your head. */
	static final Set<Prayer> NATIVE_OVERHEADS = EnumSet.of(
		Prayer.PROTECT_FROM_MAGIC,
		Prayer.PROTECT_FROM_MISSILES,
		Prayer.PROTECT_FROM_MELEE,
		Prayer.RETRIBUTION,
		Prayer.REDEMPTION,
		Prayer.SMITE
	);

	static
	{
		Map<Prayer, Integer> m = new EnumMap<>(Prayer.class);
		m.put(Prayer.THICK_SKIN, SpriteID.Prayeron.THICK_SKIN);
		m.put(Prayer.BURST_OF_STRENGTH, SpriteID.Prayeron.BURST_OF_STRENGTH);
		m.put(Prayer.CLARITY_OF_THOUGHT, SpriteID.Prayeron.CLARITY_OF_THOUGHT);
		m.put(Prayer.SHARP_EYE, SpriteID.Prayeron.SHARP_EYE);
		m.put(Prayer.MYSTIC_WILL, SpriteID.Prayeron.MYSTIC_WILL);
		m.put(Prayer.ROCK_SKIN, SpriteID.Prayeron.ROCK_SKIN);
		m.put(Prayer.SUPERHUMAN_STRENGTH, SpriteID.Prayeron.SUPERHUMAN_STRENGTH);
		m.put(Prayer.IMPROVED_REFLEXES, SpriteID.Prayeron.IMPROVED_REFLEXES);
		m.put(Prayer.RAPID_RESTORE, SpriteID.Prayeron.RAPID_RESTORE);
		m.put(Prayer.RAPID_HEAL, SpriteID.Prayeron.RAPID_HEAL);
		m.put(Prayer.PROTECT_ITEM, SpriteID.Prayeron.PROTECT_ITEM);
		m.put(Prayer.HAWK_EYE, SpriteID.Prayeron.HAWK_EYE);
		m.put(Prayer.MYSTIC_LORE, SpriteID.Prayeron.MYSTIC_LORE);
		m.put(Prayer.STEEL_SKIN, SpriteID.Prayeron.STEEL_SKIN);
		m.put(Prayer.ULTIMATE_STRENGTH, SpriteID.Prayeron.ULTIMATE_STRENGTH);
		m.put(Prayer.INCREDIBLE_REFLEXES, SpriteID.Prayeron.INCREDIBLE_REFLEXES);
		m.put(Prayer.PROTECT_FROM_MAGIC, SpriteID.Prayeron.PROTECT_FROM_MAGIC);
		m.put(Prayer.PROTECT_FROM_MISSILES, SpriteID.Prayeron.PROTECT_FROM_MISSILES);
		m.put(Prayer.PROTECT_FROM_MELEE, SpriteID.Prayeron.PROTECT_FROM_MELEE);
		m.put(Prayer.EAGLE_EYE, SpriteID.Prayeron.EAGLE_EYE);
		m.put(Prayer.MYSTIC_MIGHT, SpriteID.Prayeron.MYSTIC_MIGHT);
		m.put(Prayer.RETRIBUTION, SpriteID.Prayeron.RETRIBUTION);
		m.put(Prayer.REDEMPTION, SpriteID.Prayeron.REDEMPTION);
		m.put(Prayer.SMITE, SpriteID.Prayeron.SMITE);
		m.put(Prayer.PRESERVE, SpriteID.Prayeron.PRESERVE);
		m.put(Prayer.CHIVALRY, SpriteID.Prayeron.CHIVALRY);
		m.put(Prayer.PIETY, SpriteID.Prayeron.PIETY);
		m.put(Prayer.DEADEYE, SpriteID.Prayeron.DEADEYE);
		m.put(Prayer.MYSTIC_VIGOUR, SpriteID.Prayeron.MYSTIC_VIGOUR);
		m.put(Prayer.RIGOUR, SpriteID.Prayeron.RIGOUR);
		m.put(Prayer.AUGURY, SpriteID.Prayeron.AUGURY);
		SPRITES = Collections.unmodifiableMap(m);
	}

	private PrayerIcons()
	{
	}
}

package com.prayeroverhead;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("prayeroverhead")
public interface PrayerOverheadConfig extends Config
{
	@ConfigItem(
		keyName = "includeNativeOverheads",
		name = "Include protection prayers",
		description = "Also show Protect from Magic/Missiles/Melee, Smite, Retribution and Redemption in the row. The game already draws these over your head",
		position = 1
	)
	default boolean includeNativeOverheads()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showHighlight",
		name = "Show highlight",
		description = "Draw each icon on the glowing background a selected prayer has in the prayer tab",
		position = 2
	)
	default boolean showHighlight()
	{
		return true;
	}

	@Range(min = 0, max = 40)
	@ConfigItem(
		keyName = "iconSize",
		name = "Icon size",
		description = "Width and height of each icon, in pixels. 0 matches the height of the game's protection prayer icon",
		position = 3
	)
	default int iconSize()
	{
		return 0;
	}

	@Range(min = 0, max = 20)
	@ConfigItem(
		keyName = "spacing",
		name = "Spacing",
		description = "Gap between icons, and between the row and the game's protection prayer icon, in pixels",
		position = 4
	)
	default int spacing()
	{
		return 2;
	}

	@Range(min = -100, max = 100)
	@ConfigItem(
		keyName = "heightOffset",
		name = "Height offset",
		description = "Nudge the row up (positive) or down (negative), in pixels. 0 lines it up with the game's protection prayer icon",
		position = 5
	)
	default int heightOffset()
	{
		return 0;
	}

	@Range(min = -100, max = 100)
	@ConfigItem(
		keyName = "horizontalOffset",
		name = "Horizontal offset",
		description = "Nudge the row left (negative) or right (positive), in pixels. 0 puts it just right of the game's protection prayer icon",
		position = 6
	)
	default int horizontalOffset()
	{
		return 0;
	}
}

package com.prayeroverhead;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Prayer;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Slf4j
public class PrayerOverheadOverlay extends Overlay
{
	/**
	 * Where the game draws its own protection prayer icon: its top-left corner sits at this
	 * pixel offset from the point NATIVE_Z world units above the player's logical height.
	 */
	private static final int NATIVE_Z = 15;
	private static final int NATIVE_LEFT = -12;
	private static final int NATIVE_TOP = -30;

	private final Client client;
	private final SpriteManager spriteManager;
	private final PrayerOverheadConfig config;

	/** Icon-on-highlight images by icon sprite id, so they aren't rebuilt every frame */
	private final Map<Integer, BufferedImage> highlighted = new HashMap<>();
	private boolean loggedSizes;

	@Inject
	PrayerOverheadOverlay(Client client, SpriteManager spriteManager, PrayerOverheadConfig config)
	{
		this.client = client;
		this.spriteManager = spriteManager;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		// Sprites load asynchronously, so any of these may be null for the first frame or two
		BufferedImage nativeIcon = spriteManager.getSprite(SpriteID.HEADICONS_PRAYER, 0);
		BufferedImage glow = config.showHighlight() ? spriteManager.getSprite(SpriteID.Prayerglow.ACTIVATED, 0) : null;
		if (nativeIcon == null)
		{
			return null;
		}

		// Collect icons for every active prayer, in prayer book order
		List<BufferedImage> icons = new ArrayList<>();
		for (Map.Entry<Prayer, Integer> entry : PrayerIcons.SPRITES.entrySet())
		{
			Prayer prayer = entry.getKey();
			if (!client.isPrayerActive(prayer))
			{
				continue;
			}
			if (!config.includeNativeOverheads() && PrayerIcons.NATIVE_OVERHEADS.contains(prayer))
			{
				continue;
			}
			BufferedImage icon = spriteManager.getSprite(entry.getValue(), 0);
			if (icon != null)
			{
				icons.add(glow != null ? withHighlight(entry.getValue(), icon, glow) : icon);
			}
		}

		if (icons.isEmpty())
		{
			return null;
		}

		if (!loggedSizes)
		{
			loggedSizes = true;
			BufferedImage first = icons.get(0);
			log.debug("Sprite sizes: native {}x{}, glow {}, first icon {}x{}", nativeIcon.getWidth(), nativeIcon.getHeight(),
				glow == null ? "none" : glow.getWidth() + "x" + glow.getHeight(), first.getWidth(), first.getHeight());
		}

		// Project the point the game draws its protection icon from
		Point loc = player.getCanvasImageLocation(nativeIcon, player.getLogicalHeight() + NATIVE_Z);
		if (loc == null)
		{
			return null;
		}
		int nativeLeft = loc.getX() + nativeIcon.getWidth() / 2 + NATIVE_LEFT;
		int nativeTop = loc.getY() + nativeIcon.getHeight() / 2 + NATIVE_TOP;

		// Match the protection icon's height, sit level with it, and start just to its right
		int size = config.iconSize() > 0 ? config.iconSize() : nativeIcon.getHeight();
		int spacing = config.spacing();
		int x = nativeLeft + nativeIcon.getWidth() + spacing + config.horizontalOffset();
		int y = nativeTop + (nativeIcon.getHeight() - size) / 2 - config.heightOffset();

		// Default scaling is nearest-neighbour, which looks rough on these small sprites
		Object oldInterpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		for (BufferedImage icon : icons)
		{
			graphics.drawImage(icon, x, y, size, size, null);
			x += size + spacing;
		}
		if (oldInterpolation != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
		}

		return null;
	}

	/** Draws the icon centered on the activated-prayer background, like a selected prayer in the prayer tab */
	private BufferedImage withHighlight(int spriteId, BufferedImage icon, BufferedImage glow)
	{
		return highlighted.computeIfAbsent(spriteId, id ->
		{
			int w = Math.max(icon.getWidth(), glow.getWidth());
			int h = Math.max(icon.getHeight(), glow.getHeight());
			BufferedImage combined = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = combined.createGraphics();
			g.drawImage(glow, (w - glow.getWidth()) / 2, (h - glow.getHeight()) / 2, null);
			g.drawImage(icon, (w - icon.getWidth()) / 2, (h - icon.getHeight()) / 2, null);
			g.dispose();
			return combined;
		});
	}
}

package com.prayeroverhead;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Prayer Overhead",
	description = "Shows every active prayer as a row of icons above your character",
	tags = {"prayer", "piety", "rigour", "augury", "overhead", "icon"}
)
public class PrayerOverheadPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PrayerOverheadOverlay overlay;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	@Provides
	PrayerOverheadConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PrayerOverheadConfig.class);
	}
}

package com.prayeroverhead;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PrayerOverheadPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PrayerOverheadPlugin.class);
		RuneLite.main(args);
	}
}
